import{j as e}from"./motion-framer-CfsFicUq.js";import{S as t}from"./ServicePageLayout-mswu4ys3.js";import{S as o}from"./smartphone-j2eotmKX.js";import"./motion-gsap-a3sj5zmn.js";import"./button-U6YGi0FM.js";import"./index-Cp_-rLRh.js";import"./PageBanner-DI0ZdnbO.js";import"./Breadcrumbs-C5_K0Tm4.js";import"./chevron-right-54xlIn0d.js";function h(){return e.jsx(t,{title:"USSD Codes",subtitle:"Interactive Menus That Work on Every Phone in Kenya",description:"Build interactive USSD menus that run on any mobile phone — no internet, no smartphone, no app. MobiWave provisions shared and dedicated USSD shortcodes through the Communications Authority of Kenya (CAK), wires them to your REST API, and lets you trigger M-Pesa STK Push from any menu step. Perfect for banking, payments, surveys and customer self-service in areas with limited connectivity.",icon:o,stats:[{value:"KES 11,000",label:"Shared Setup +VAT"},{value:"KES 40,000",label:"Dedicated / Month +VAT"},{value:"All phones",label:"No Internet Needed"},{value:"24/7",label:"Nairobi Support"}],features:["Works on every GSM phone — feature phones included, no data or app","No internet required; menus run over the carrier signalling channel","Custom multi-level menu flows with branching logic","Real-time session responses and live input capture","Swahili and English menu localization out of the box","REST API + webhook integration with session state management","Per-session analytics and drop-off reporting","Shared and dedicated shortcodes to fit any budget","M-Pesa STK Push triggered from any menu step","Sandbox test-bed for building and validating menus before go-live"],benefits:["Reach customers in rural and low-connectivity areas where smartphones and data are scarce","Instant menu responses with no app install or onboarding friction","Cost-effective for both your business and your customers","Secure, carrier-grade transactions on Safaricom, Airtel and Telkom","Collect M-Pesa payments inside the same menu flow — no channel switching","24/7 local Nairobi support via phone, email and WhatsApp"],useCases:[{title:"Mobile banking & wallets",description:"Balance checks, mini-statements, transfers and PIN changes via USSD on any phone."},{title:"M-Pesa collections",description:"Trigger STK Push inside a USSD menu for contributions, dues, airtime top-up and bill pay."},{title:"Customer surveys",description:"Run interactive USSD questionnaires and polls with branching questions and instant scoring."},{title:"Information services",description:"Deliver crop prices, exam results, clinic schedules and product availability without data."},{title:"Account management",description:"Let customers register, subscribe, pause or upgrade services entirely through the menu."},{title:"Voting & registration",description:"Conduct elections, membership drives and event check-in with one-tap confirmations."},{title:"Loyalty & rewards",description:"Redeem points, check balances and claim airtime or data rewards from the menu."},{title:"Agricultural advisory",description:"Push weather alerts and farming tips to smallholder farmers on the simplest handsets."}],howItWorks:[{step:"1",title:"Choose shared or dedicated",description:"Shared USSD is KES 11,000 setup + KES 8,000/month +VAT and goes live fast on a sub-keyword. Dedicated is your own code at KES 40,000 up-front + KES 40,000/month +VAT for full branding and control."},{step:"2",title:"Apply through the CAK",description:"Shortcodes are allocated by the Communications Authority of Kenya. MobiWave prepares and submits the application with your business registration and a signed company letterhead, so you skip the paperwork."},{step:"3",title:"Carrier provisioning",description:"Safaricom, Airtel and Telkom provision the code on their signalling infrastructure. Shared codes can be live within days; dedicated codes follow CAK approval, which typically takes several weeks."},{step:"4",title:"Build in the test-bed",description:"Use the 30-day test-bed environment (KES 32,000 +VAT) to develop menus, wire your API and validate session flows before real traffic reaches your systems."},{step:"5",title:"Go live",description:"Point your menus at your REST endpoint or webhook. Real subscriber sessions flow through, with per-session analytics and drop-off reporting in the MobiWave dashboard."},{step:"6",title:"Bundle with M-Pesa, SMS & WhatsApp",description:"Add M-Pesa STK Push, bulk SMS, WhatsApp and airtime rewards from the same MobiWave account — one billing line, one support contact."}],comparisonTable:{headers:["MobiWave","Africa's Talking","Celcom Africa","Twilio"],note:"MobiWave figures are published rates (VAT extra). Competitor USSD models are typically quote-based — confirm before contract. Twilio has no native Kenya USSD shortcode product.",rows:[{name:"Shared USSD code",cells:[{text:"KES 11,000 setup + KES 8,000/mo",highlight:!0},{text:"Available (quote)"},{text:"Available"},{text:"Not supported"}]},{name:"Dedicated USSD code",cells:[{text:"KES 40,000 setup + KES 40,000/mo",highlight:!0},{text:"Available (quote)"},{text:"Available"},{text:"Not supported"}]},{name:"Test-bed / sandbox",cells:[{text:"KES 32,000 / 30 days",highlight:!0},{text:"Yes"},{text:"Yes"},{text:"N/A"}]},{name:"M-Pesa STK Push from menu",cells:[{text:"Native, bundled",highlight:!0},{text:"Yes (add-on)"},{text:"Yes"},{text:"No"}]},{name:"CAK shortcode application",cells:[{text:"Handled for you",highlight:!0},{text:"Self-service docs"},{text:"Assisted"},{text:"No local team"}]},{name:"Local 24/7 support",cells:[{text:"Phone + WhatsApp",highlight:!0},{text:"Developer-only"},{text:"Business hours"},{text:"No local team"}]},{name:"Bundle with SMS & WhatsApp",cells:[{text:"One account",highlight:!0},{text:"Add-ons"},{text:"Add-ons"},{text:"Separate products"}]}]},pricing:[{title:"Dedicated USSD",price:"KES 110,000",unit:" +VAT",features:["Up-front fee: KES 40,000 +VAT","Monthly fee: KES 40,000 +VAT","Dedicated USSD code","Full customization","Customer charged for access","24/7 support","API integration"]},{title:"Test-Bed Service",price:"KES 32,000",unit:" +VAT",features:["30-day test environment","Development access","Testing capabilities","Extension: KES 32,000 +VAT","Technical support"]},{title:"Shared USSD",price:"KES 11,000",unit:" setup +VAT",features:["Shared USSD code","Monthly fee: KES 8,000 +VAT","Cost-effective","Standard support"]}],faqs:[{question:"How much does a USSD code cost in Kenya in 2026?",answer:"MobiWave offers three options. Shared USSD is KES 11,000 setup + KES 8,000/month (+VAT). Dedicated USSD is KES 110,000 total — KES 40,000 up-front + KES 40,000/month (+VAT) — for your own branded code. A 30-day test-bed for development is KES 32,000 (+VAT). All prices are exclusive of VAT; end-user per-session charges from the carrier are billed to your customers, not to you."},{question:"How do I apply for a USSD shortcode from the CAK?",answer:"USSD shortcodes in Kenya are allocated by the Communications Authority of Kenya (CAK). MobiWave handles the application on your behalf using your business registration, KRA PIN and a signed, stamped authorisation letter on company letterhead. Dedicated codes require CAK approval; shared codes run on MobiWave’s pre-approved pool so they can go live much faster."},{question:"How long does it take to get a USSD code live?",answer:"Shared USSD codes can be live within a few days once your menus are built. Dedicated codes must pass CAK approval and carrier provisioning, which typically takes several weeks. We recommend starting on the test-bed in parallel so development is finished the moment the code is allocated."},{question:"What is the difference between shared and dedicated USSD?",answer:"A shared code puts your service on a sub-keyword of MobiWave’s allocated shortcode (e.g. *XYZ*5#) — cheaper and faster, ideal for pilots and SMEs. A dedicated code is yours alone (e.g. *123#), fully branded and unrestricted, suited to banks, SACCOs and nationwide programs that need top-of-mind recall."},{question:"Do my customers pay to use the USSD menu?",answer:"Yes. The carrier bills the end user a per-session charge (typically KES 1–5 depending on the network and session length) directly on their airtime. Your business pays only the MobiWave service fee — you never absorb the subscriber’s connectivity cost."},{question:"Can I collect M-Pesa payments inside a USSD menu?",answer:"Yes. MobiWave can trigger an M-Pesa STK Push from any step in your USSD flow — for contributions, dues, airtime top-up or bill payment — and reconcile the result back into the same session via webhook. No third-party aggregator required."},{question:"Do users need internet or a smartphone for USSD?",answer:"No. USSD runs over the GSM signalling channel on every feature phone and smartphone alike. That is its core advantage: you reach customers who have no data, no smartphone and no app — the majority of subscribers in many Kenyan counties."},{question:"Can the menus be in Swahili?",answer:"Yes. MobiWave USSD supports multi-language menus, including Swahili and English, with the language selectable by the subscriber inside the first menu level."},{question:"Is there an API to power the menus?",answer:"Yes. Each menu step calls your REST endpoint (or webhook) with the session id and user input; you return the next screen. MobiWave manages session state, timeouts and analytics so your backend stays simple."},{question:"How is MobiWave different from Africa’s Talking for USSD?",answer:"Both provide USSD infra, but MobiWave bundles M-Pesa STK Push, bulk SMS, WhatsApp and airtime rewards on one Kenyan account with managed CAK onboarding and 24/7 local phone/WhatsApp support. Africa’s Talking is strong for self-service developer APIs; MobiWave adds the managed, non-developer onboarding and the payments bundle in one billing line."}]})}export{h as USSDCodes};
